'use client';
import {useEffect,useRef,useState} from 'react';
import {hotelClient,hotelRpc} from '@/lib/pilot';
import {bankBalanceInput,bankCloseMoney} from '@/lib/cashier-bank-close';
import {financialImportHeaders} from '@/lib/financial-import-csv';
import {readFinancialStage,readFinancialStageStatus,validateFinancialStage,type FinancialStageRequest} from '@/lib/financial-migration-stage';
import type {HandoffScope} from '@/lib/cashier-handoff';
export function FinancialMigrationUpload({scope,onStaged}:{scope:HandoffScope;onStaged:(batch:string)=>void}){
 const [provider,setProvider]=useState(''),[batch,setBatch]=useState(''),[cutover,setCutover]=useState(''),[csv,setCsv]=useState(''),[hash,setHash]=useState(''),[filename,setFilename]=useState(''),[totals,setTotals]=useState({receivable:'',prepayment:'',security:''}),[pending,setPending]=useState<FinancialStageRequest|null>(null),[preview,setPreview]=useState<ReturnType<typeof readFinancialStage>|null>(null),[error,setError]=useState(''),[busy,setBusy]=useState(false),[ready,setReady]=useState(false),[cancelConfirmed,setCancelConfirmed]=useState(false),[message,setMessage]=useState('');
 const alive=useRef(false),lock=useRef(false),fileGeneration=useRef(0),key=['irp.financial.stage.v1',scope.tenant,scope.property,scope.actor].join(':');
 useEffect(()=>{alive.current=true;try{const raw=sessionStorage.getItem(key);if(raw){const r=JSON.parse(raw) as FinancialStageRequest;validateFinancialStage(r);if(r.scope.tenant!==scope.tenant||r.scope.property!==scope.property||r.scope.actor!==scope.actor)throw Error('Saved upload belongs to another workspace.');setPending(r)}setReady(true)}catch(e){setError(e instanceof Error?e.message:'Unable to recover upload.')}return()=>{alive.current=false;fileGeneration.current++}},[key]);
 async function identify(){const result=await hotelClient().auth.getUser();if(result.error||result.data.user?.id!==scope.actor)throw Error('Sign-in changed. Reopen migration.');}
 async function upload(file:File|undefined){const generation=++fileGeneration.current;setCsv('');setHash('');setFilename('');setPreview(null);if(!file)return;try{if(file.size>1048576)throw Error('The financial CSV must be 1 MB or smaller.');const bytes=await file.arrayBuffer(),text=new TextDecoder('utf-8',{fatal:true}).decode(bytes),digest=await crypto.subtle.digest('SHA-256',bytes);if(alive.current&&generation===fileGeneration.current){setCsv(text);setHash(Array.from(new Uint8Array(digest),b=>b.toString(16).padStart(2,'0')).join(''));setFilename(file.name)}}catch(e){if(alive.current&&generation===fileGeneration.current)setError(e instanceof Error?e.message:'Unable to read file.')}}
 async function stage(kind:'save'|'check'|'cancel'='save'){
  if(lock.current||!ready)return;lock.current=true;setBusy(true);setError('');setMessage('');
  try{await identify();let r=pending;
   if(!r){if(kind!=='save')throw Error('Choose a saved upload.');r={id:crypto.randomUUID(),scope,provider:provider.trim(),sourceBatch:batch.trim(),cutover,csv,exportHash:hash,totals:{receivable:bankBalanceInput(totals.receivable),prepayment:bankBalanceInput(totals.prepayment),security:bankBalanceInput(totals.security)}};validateFinancialStage(r);if(sessionStorage.getItem(key))throw Error('Recover the saved upload first.');sessionStorage.setItem(key,JSON.stringify(r));setPending(r)}
   const args={p_tenant:scope.tenant,p_property:scope.property,p_request:r.id};let result:ReturnType<typeof readFinancialStage>|null=null,cancelled=false;
   if(kind==='save'){const rows=validateFinancialStage(r);result=readFinancialStage(await hotelRpc('stage_financial_migration',{...args,p_provider:r.provider,p_source_batch:r.sourceBatch,p_export_sha256:r.exportHash,p_cutover:r.cutover,p_rows:rows,p_totals:r.totals}),r)}
   else{if(kind==='cancel'){if(!cancelConfirmed)throw Error('Confirm stopping this upload.');await hotelRpc('cancel_financial_migration_stage',{...args,p_confirmed:true})}const status=readFinancialStageStatus(await hotelRpc('financial_migration_stage_status',args),r);result=status.preview;cancelled=status.cancelled;}
   await identify();if(alive.current){if(result||cancelled){sessionStorage.removeItem(key);setPending(null);setCancelConfirmed(false);setPreview(result);setCsv('');setHash('');setFilename('');setBatch('');if(result)onStaged(result.batch);else setMessage('Upload request cancelled. Choose a file to start again.')}else setMessage('No saved upload found. Retry or cancel this request.')}
  }catch(e){if(alive.current)setError(e instanceof Error?e.message:'Unable to save migration preview.')}finally{lock.current=false;if(alive.current)setBusy(false)}
 }
 function template(){const url=URL.createObjectURL(new Blob([financialImportHeaders.join(',')+'\r\n'],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='iratepilot-financial-openings.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
 return <section className="card pilot-settings"><h2>Bring opening balances</h2><p>Match each financial item to an imported reservation. Enter the three control totals from your source PMS separately.</p><button type="button" className="secondary" onClick={template}>Download financial CSV template</button><fieldset disabled={busy||!!pending||!ready}><label className="field">Source PMS code<input value={provider} onChange={e=>setProvider(e.target.value)}/></label><label className="field">Source batch reference<input value={batch} onChange={e=>setBatch(e.target.value)}/></label><label className="field">Cutover date<input type="date" value={cutover} onChange={e=>setCutover(e.target.value)}/></label><label className="field">Financial CSV<input type="file" accept=".csv,text/csv" onChange={e=>{void upload(e.target.files?.[0]);e.target.value=''}}/></label><p>{filename}</p>{(['receivable','prepayment','security'] as const).map(category=><label className="field" key={category}>{category==='receivable'?'Source receivables total':category==='prepayment'?'Source prepayments total':'Source security funds total'}<input inputMode="decimal" value={totals[category]} onChange={e=>setTotals({...totals,[category]:e.target.value})}/></label>)}</fieldset><button type="button" disabled={busy||!ready||(!pending&&!csv)} onClick={()=>void stage()}>{pending?'Retry saved financial preview':'Save financial preview'}</button>{pending&&<><p>The upload outcome is unresolved. Retry restores the same batch.</p><button type="button" disabled={busy} onClick={()=>void stage('check')}>Check upload outcome</button><label><input type="checkbox" checked={cancelConfirmed} disabled={busy} onChange={e=>setCancelConfirmed(e.target.checked)}/>Stop this upload if not saved</label><button type="button" disabled={busy||!cancelConfirmed} onClick={()=>void stage('cancel')}>Cancel upload request</button></>}{message&&<p role="status">{message}</p>}{error&&<p role="alert">{error}</p>}{preview&&<><p role="status">Preview saved. No opening balances were posted.</p><p>{preview.reconciled?'Source totals reconcile.':'Resolve the source errors before posting.'}</p>{preview.controlErrors.map(e=><p key={e}>{e.replaceAll('_',' ')}</p>)}<table><thead><tr><th>Source item</th><th>Category</th><th>Amount</th><th>Review</th></tr></thead><tbody>{preview.rows.map(row=><tr key={row.number}><td>{row.sourceId}</td><td>{row.category}</td><td>{bankCloseMoney(row.amount)}</td><td>{row.valid?'Valid':row.errors.map(e=>e.replaceAll('_',' ')).join('; ')}</td></tr>)}</tbody></table></>}</section>;
}
